static void qeth_bridgeport_query_support ( struct qeth_card * card ) { struct qeth_cmd_buffer * iob ; struct _qeth_sbp_cbctl cbctl ; QETH_CARD_TEXT ( card , 2 , "brqsuppo" ) ; iob = qeth_sbp_build_cmd ( card , IPA_SBP_QUERY_COMMANDS_SUPPORTED , SBP_DATA_SIZEOF ( query_cmds_supp ) ) ; if ( qeth_send_ipa_cmd ( card , iob , qeth_bridgeport_query_support_cb , & cbctl ) ) { card -> options . sbp . role = QETH_SBP_ROLE_NONE ; card -> options . sbp . supported_funcs = 0 ; return ; } card -> options . sbp . supported_funcs = cbctl . data . supported ; } 